// AI Insights Page
// Dedicated page for AI-powered financial recommendations

import React, { useState, useEffect } from 'react';
import axios from 'axios';
import Navbar from '../components/Navbar';
import AIInsights from '../components/AIInsights';
import './AIInsightsPage.css';

function AIInsightsPage() {
  const [transactions, setTransactions] = useState([]);
  const [budget, setBudget] = useState(null);
  const [loading, setLoading] = useState(true);

  const token = localStorage.getItem('token');

  useEffect(() => {
    fetchData();
  }, []);

  const fetchData = async () => {
    try {
      setLoading(true);

      // Fetch transactions
      const transResponse = await axios.get('http://localhost:5000/api/transactions', {
        headers: { Authorization: `Bearer ${token}` }
      });
      setTransactions(transResponse.data);

      // Fetch budget
      try {
        const budgetResponse = await axios.get('http://localhost:5000/api/budget/get', {
          headers: { Authorization: `Bearer ${token}` }
        });
        setBudget(budgetResponse.data);
      } catch (error) {
        setBudget(null);
      }
    } catch (error) {
      console.log('Error fetching data:', error.message);
    } finally {
      setLoading(false);
    }
  };

  // Calculate statistics
  const totalIncome = transactions
    .filter(t => t.type === 'income')
    .reduce((sum, t) => sum + parseFloat(t.amount), 0);

  const totalExpense = transactions
    .filter(t => t.type === 'expense')
    .reduce((sum, t) => sum + parseFloat(t.amount), 0);

  const balance = totalIncome - totalExpense;
  const savingsRate = totalIncome > 0 ? ((balance / totalIncome) * 100).toFixed(2) : 0;

  // Get top categories
  const categorySpending = {};
  transactions
    .filter(t => t.type === 'expense')
    .forEach(t => {
      if (!categorySpending[t.category]) {
        categorySpending[t.category] = 0;
      }
      categorySpending[t.category] += parseFloat(t.amount);
    });

  const topCategories = Object.entries(categorySpending)
    .sort((a, b) => b[1] - a[1])
    .slice(0, 3);

  return (
    <div className="ai-insights-page">
      <Navbar />

      {/* Header */}
      <div className="ai-insights-header">
        <h1>🤖 AI Financial Insights</h1>
        <p>Get personalized financial recommendations powered by AI</p>
      </div>

      {/* Summary Cards */}
      <div className="ai-summary-cards">
        <div className="summary-card">
          <div className="card-icon">💰</div>
          <div className="card-content">
            <h3>Total Income</h3>
            <p className="card-amount">₹ {totalIncome.toFixed(2)}</p>
          </div>
        </div>

        <div className="summary-card">
          <div className="card-icon">💸</div>
          <div className="card-content">
            <h3>Total Expenses</h3>
            <p className="card-amount">₹ {totalExpense.toFixed(2)}</p>
          </div>
        </div>

        <div className="summary-card">
          <div className="card-icon">💳</div>
          <div className="card-content">
            <h3>Balance</h3>
            <p className={`card-amount ${balance >= 0 ? 'positive' : 'negative'}`}>
              ₹ {balance.toFixed(2)}
            </p>
          </div>
        </div>

        <div className="summary-card">
          <div className="card-icon">📈</div>
          <div className="card-content">
            <h3>Savings Rate</h3>
            <p className="card-amount">{savingsRate}%</p>
          </div>
        </div>
      </div>

      {/* AI Insights Component */}
      <div className="ai-insights-section">
        <h2>✨ AI Recommendations</h2>
        <AIInsights />
      </div>

      {/* Spending Analysis */}
      {topCategories.length > 0 && (
        <div className="spending-analysis">
          <h2>📊 Your Spending Analysis</h2>
          <div className="analysis-content">
            <div className="analysis-card">
              <h3>Top Spending Categories</h3>
              <div className="categories-list">
                {topCategories.map((category, index) => (
                  <div key={index} className="category-item">
                    <span className="category-name">{category[0]}</span>
                    <span className="category-amount">₹ {category[1].toFixed(2)}</span>
                  </div>
                ))}
              </div>
            </div>

            <div className="analysis-card">
              <h3>Financial Health</h3>
              <div className="health-indicators">
                <div className="health-item">
                  <span className="health-label">Income Status</span>
                  <span className={`health-value ${totalIncome > 0 ? 'good' : 'warning'}`}>
                    {totalIncome > 0 ? '✅ Positive' : '⚠️ No Income'}
                  </span>
                </div>
                <div className="health-item">
                  <span className="health-label">Expense Status</span>
                  <span className={`health-value ${totalExpense < totalIncome ? 'good' : 'warning'}`}>
                    {totalExpense < totalIncome ? '✅ Controlled' : '⚠️ High'}
                  </span>
                </div>
                <div className="health-item">
                  <span className="health-label">Savings Status</span>
                  <span className={`health-value ${savingsRate > 20 ? 'good' : 'warning'}`}>
                    {savingsRate > 20 ? '✅ Excellent' : '⚠️ Needs Work'}
                  </span>
                </div>
                {budget && (
                  <div className="health-item">
                    <span className="health-label">Budget Status</span>
                    <span className={`health-value ${totalExpense <= budget.monthlyLimit ? 'good' : 'warning'}`}>
                      {totalExpense <= budget.monthlyLimit ? '✅ On Track' : '⚠️ Over Budget'}
                    </span>
                  </div>
                )}
              </div>
            </div>
          </div>
        </div>
      )}

      {/* AI Tips */}
      <div className="ai-tips">
        <h2>💡 Smart Financial Tips</h2>
        <div className="tips-grid">
          <div className="tip-card">
            <div className="tip-icon">🎯</div>
            <h3>Set Clear Goals</h3>
            <p>Define your financial goals and track progress regularly</p>
          </div>

          <div className="tip-card">
            <div className="tip-icon">📊</div>
            <h3>Track Spending</h3>
            <p>Monitor your expenses to identify areas for improvement</p>
          </div>

          <div className="tip-card">
            <div className="tip-icon">💰</div>
            <h3>Build Emergency Fund</h3>
            <p>Save 3-6 months of expenses for unexpected situations</p>
          </div>

          <div className="tip-card">
            <div className="tip-icon">📈</div>
            <h3>Increase Income</h3>
            <p>Look for opportunities to increase your income streams</p>
          </div>

          <div className="tip-card">
            <div className="tip-icon">🛍️</div>
            <h3>Reduce Expenses</h3>
            <p>Cut unnecessary expenses and optimize your spending</p>
          </div>

          <div className="tip-card">
            <div className="tip-icon">🏦</div>
            <h3>Invest Wisely</h3>
            <p>Once you have savings, consider investing for growth</p>
          </div>
        </div>
      </div>

      {/* Action Items */}
      <div className="action-items">
        <h2>✅ Recommended Actions</h2>
        <div className="actions-list">
          {totalExpense > totalIncome && (
            <div className="action-item urgent">
              <span className="action-icon">🚨</span>
              <div className="action-content">
                <h4>Reduce Expenses</h4>
                <p>Your expenses exceed your income. Review and reduce spending immediately.</p>
              </div>
            </div>
          )}

          {savingsRate < 10 && (
            <div className="action-item warning">
              <span className="action-icon">⚠️</span>
              <div className="action-content">
                <h4>Improve Savings Rate</h4>
                <p>Your savings rate is below 10%. Try to increase it to at least 20%.</p>
              </div>
            </div>
          )}

          {budget && totalExpense > budget.monthlyLimit && (
            <div className="action-item urgent">
              <span className="action-icon">💸</span>
              <div className="action-content">
                <h4>Over Budget</h4>
                <p>You've exceeded your monthly budget. Review your spending categories.</p>
              </div>
            </div>
          )}

          {topCategories.length > 0 && topCategories[0][1] > totalExpense * 0.5 && (
            <div className="action-item warning">
              <span className="action-icon">📊</span>
              <div className="action-content">
                <h4>High Category Spending</h4>
                <p>{topCategories[0][0]} accounts for over 50% of your expenses. Consider reducing it.</p>
              </div>
            </div>
          )}

          {savingsRate >= 20 && (
            <div className="action-item success">
              <span className="action-icon">✅</span>
              <div className="action-content">
                <h4>Great Savings Rate!</h4>
                <p>You're saving {savingsRate}% of your income. Keep up the excellent work!</p>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

export default AIInsightsPage;
